  @case 'replace husk (no kinds) parks nothing -- its members keep sounding'  [harness]  @ 469-475
  @case 'replace: removing the region restores the parked chord to the take'  [harness]  @ 479-494
  @case 'G4: replace arp + parked chord are byte-identical across rebuild -> flush'  [harness]  @ 498-510
